<?php
declare(strict_types=1);

function report_rows(): array {
    $where=['company_id=?'];$params=[tenant_id()];
    $filters=[
        'sector'=>'sector',
        'user'=>'assigned_user',
        'status'=>'asset_status',
        'windows'=>'windows_version',
    ];
    foreach($filters as $input=>$column){$value=trim((string)($_GET[$input]??''));if($value==='')continue;if($input==='user'){$where[]="$column LIKE ?";$params[]="%$value%";}else{$where[]="$column=?";$params[]=$value;}}
    $pcs=query('SELECT * FROM computers WHERE '.implode(' AND ',$where).' ORDER BY computer_name',$params)->fetchAll();
    $disks=[];if($pcs){$ids=array_column($pcs,'id');$marks=implode(',',array_fill(0,count($ids),'?'));foreach(query("SELECT * FROM disks WHERE computer_id IN ($marks) ORDER BY computer_id,id",$ids)->fetchAll() as $disk)$disks[$disk['computer_id']][]=$disk;}
    $level=trim((string)($_GET['criticality']??''));$rows=[];
    foreach($pcs as $pc){$analysis=criticality($pc,$disks[$pc['id']]??[]);if($level!==''&&$analysis['level']!==$level)continue;$diskText=[];foreach($disks[$pc['id']]??[] as $disk)$diskText[]=trim($disk['disk_type'].' '.($disk['brand_model']??'').' '.($disk['size_gb']?($disk['size_gb'].' GB'):''));$pc['_analysis']=$analysis;$pc['_disks']=implode(' + ',$diskText)?:'Não informado';$pc['_ram_layout']=$pc['ram_sticks_count']&&$pc['ram_per_stick_gb']?$pc['ram_sticks_count'].' × '.$pc['ram_per_stick_gb'].' GB':($pc['ram_slots_detail']?:'Não informado');$rows[]=$pc;}
    return $rows;
}
function report_level_label(string $level): string { return ['critical'=>'Crítico','attention'=>'Atenção','ok'=>'Adequado'][$level]??$level; }
function report_status_class(string $status): string { return $status==='Em uso'?'ok':($status==='Baixado'?'critical':'attention'); }

if($path==='/reports/excel'){
    $rows=report_rows();$filename='inventario-'.preg_replace('/[^a-z0-9_-]+/','-',strtolower((string)(company()['slug']??'empresa'))).'-'.date('Y-m-d').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['Computador','Setor','Usuário','Situação','Ano','Fabricante','Modelo','Processador','RAM total','Configuração RAM','Windows','Discos','Criticidade','Pontuação','Motivos'],';');foreach($rows as $pc)fputcsv($out,[$pc['computer_name'],$pc['sector'],$pc['assigned_user'],$pc['asset_status'],$pc['manufacture_year'],$pc['manufacturer'],$pc['model'],$pc['processor'],$pc['ram_gb']?($pc['ram_gb'].' GB'):'',$pc['_ram_layout'],$pc['windows_version'],$pc['_disks'],report_level_label($pc['_analysis']['level']),$pc['_analysis']['score'],implode(' | ',$pc['_analysis']['reasons'])],';');fclose($out);exit;
}

if($path==='/reports/pdf'){
    $rows=report_rows();$critical=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='critical'));$attention=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='attention'));$inUse=count(array_filter($rows,fn($r)=>$r['asset_status']==='Em uso'));?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório de equipamentos · <?=e(company()['name'])?></title><style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{font:10px Arial,sans-serif;color:#182238;margin:0}header{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:3px solid <?=e(company()['primary_color']??'#173F73')?>;padding-bottom:8px;margin-bottom:10px}h1{font-size:20px;margin:0}p{margin:3px 0}.summary{display:flex;gap:8px;margin:10px 0}.summary div{border:1px solid #ccd5e2;border-radius:6px;padding:7px 12px}.summary strong{font-size:15px;display:block}table{width:100%;border-collapse:collapse}th{background:#eef2f7;text-align:left;font-size:9px}th,td{border:1px solid #d8dee8;padding:5px;vertical-align:top}.critical{color:#b42318;font-weight:bold}.attention{color:#a15c00;font-weight:bold}.ok{color:#087443;font-weight:bold}.muted{color:#64748b}footer{margin-top:8px;text-align:right;color:#64748b}@media print{button{display:none}}</style></head><body><header><div><h1>Relatório de equipamentos</h1><p><?=e(company()['name'])?></p></div><div>Emitido em <?=date('d/m/Y H:i')?></div></header><div class="summary"><div><strong><?=count($rows)?></strong>equipamentos</div><div><strong><?=$inUse?></strong>em uso</div><div><strong class="critical"><?=$critical?></strong>críticos</div><div><strong class="attention"><?=$attention?></strong>em atenção</div></div><table><thead><tr><th>Computador</th><th>Setor / usuário</th><th>Situação</th><th>Ano</th><th>Processador</th><th>RAM</th><th>Windows</th><th>Discos</th><th>Criticidade e motivos</th></tr></thead><tbody><?php foreach($rows as $pc):?><tr><td><strong><?=e($pc['computer_name'])?></strong><br><span class="muted"><?=e(trim(($pc['manufacturer']??'').' '.($pc['model']??'')))?></span></td><td><?=e($pc['sector'])?><br><?=e($pc['assigned_user'])?></td><td class="<?=report_status_class($pc['asset_status'])?>"><?=e($pc['asset_status'])?></td><td><?=e($pc['manufacture_year'])?></td><td><?=e($pc['processor'])?></td><td><?=e(($pc['ram_gb']?:'—').' GB')?><br><span class="muted"><?=e($pc['_ram_layout'])?></span></td><td><?=e($pc['windows_version'])?></td><td><?=e($pc['_disks'])?></td><td class="<?=e($pc['_analysis']['level'])?>"><?=e(report_level_label($pc['_analysis']['level']))?> (<?=$pc['_analysis']['score']?>)<br><span class="muted"><?=e(implode(' · ',$pc['_analysis']['reasons'])?:'Sem alertas')?></span></td></tr><?php endforeach?></tbody></table><footer>Inventário Amplificati · <?=count($rows)?> registro(s)</footer><script>addEventListener('load',()=>setTimeout(()=>print(),300))</script></body></html><?php exit;
}

if($path==='/reports'){
    $rows=report_rows();$critical=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='critical'));$attention=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='attention'));$adequate=count(array_filter($rows,fn($r)=>$r['_analysis']['level']==='ok'));$inUse=count(array_filter($rows,fn($r)=>$r['asset_status']==='Em uso'));$sectors=query("SELECT name FROM catalog_items WHERE company_id=? AND catalog_type='sector' AND active=1 ORDER BY name",[tenant_id()])->fetchAll(PDO::FETCH_COLUMN);$statuses=query("SELECT name FROM catalog_items WHERE company_id=? AND catalog_type='asset_status' AND active=1 ORDER BY name",[tenant_id()])->fetchAll(PDO::FETCH_COLUMN);$windows=query("SELECT name FROM catalog_items WHERE company_id=? AND catalog_type='windows_version' AND active=1 ORDER BY name",[tenant_id()])->fetchAll(PDO::FETCH_COLUMN);$query=$_GET;$exportQuery=http_build_query($query);page_start('Relatórios','reports');?><div class="grid kpis"><div class="card kpi"><strong><?=count($rows)?></strong><span>No relatório</span></div><div class="card kpi"><strong><?=$inUse?></strong><span>Em uso</span></div><div class="card kpi critical"><strong><?=$critical?></strong><span>Críticos</span></div><div class="card kpi attention"><strong><?=$attention?></strong><span>Em atenção</span></div><div class="card kpi ok"><strong><?=$adequate?></strong><span>Adequados</span></div></div><form class="filters card" method="get"><div class="field"><label>Setor</label><select name="sector"><option value="">Todos</option><?php foreach($sectors as $value):?><option <?=($_GET['sector']??'')===$value?'selected':''?>><?=e($value)?></option><?php endforeach?></select></div><div class="field"><label>Usuário</label><input name="user" value="<?=e($_GET['user']??'')?>"></div><div class="field"><label>Situação</label><select name="status"><option value="">Todas</option><?php foreach($statuses as $value):?><option <?=($_GET['status']??'')===$value?'selected':''?>><?=e($value)?></option><?php endforeach?></select></div><div class="field"><label>Windows</label><select name="windows"><option value="">Todos</option><?php foreach($windows as $value):?><option <?=($_GET['windows']??'')===$value?'selected':''?>><?=e($value)?></option><?php endforeach?></select></div><div class="field"><label>Criticidade</label><select name="criticality"><option value="">Todas</option><option value="critical" <?=($_GET['criticality']??'')==='critical'?'selected':''?>>Críticos</option><option value="attention" <?=($_GET['criticality']??'')==='attention'?'selected':''?>>Atenção</option><option value="ok" <?=($_GET['criticality']??'')==='ok'?'selected':''?>>Adequados</option></select></div><button class="btn">Aplicar filtros</button><a class="btn secondary" href="/reports">Limpar</a></form><div class="actions" style="margin:16px 0"><a class="btn" href="/reports/excel<?=$exportQuery?'?'.e($exportQuery):''?>">Exportar Excel</a><a class="btn secondary" target="_blank" href="/reports/pdf<?=$exportQuery?'?'.e($exportQuery):''?>">Salvar em PDF</a><a class="btn danger" href="/reports?criticality=critical">Ver somente críticos</a></div><div class="card table-card"><div class="card-heading"><div><h3>Equipamentos cadastrados</h3><span>Situação operacional e análise automática do parque</span></div></div><div class="table-wrap"><table data-table><thead><tr><th>Computador</th><th>Setor</th><th>Usuário</th><th>Situação</th><th>Ano</th><th>RAM</th><th>Windows</th><th>Discos</th><th>Criticidade</th><th>Motivos</th></tr></thead><tbody><?php foreach($rows as $pc):?><tr><td><a href="/computers/edit?id=<?=$pc['id']?>"><?=e($pc['computer_name'])?></a></td><td><?=e($pc['sector'])?></td><td><?=e($pc['assigned_user'])?></td><td><span class="status-dot <?=report_status_class($pc['asset_status'])?>"><i></i><?=e($pc['asset_status'])?></span></td><td><?=e($pc['manufacture_year'])?></td><td><?=e(($pc['ram_gb']?:'—').' GB')?><br><span class="muted"><?=e($pc['_ram_layout'])?></span></td><td><?=e($pc['windows_version'])?></td><td><?=e($pc['_disks'])?></td><td><span class="badge <?=e($pc['_analysis']['level'])?>"><?=e(report_level_label($pc['_analysis']['level']))?></span></td><td><?=e(implode(' · ',$pc['_analysis']['reasons'])?:'Sem alertas')?></td></tr><?php endforeach?></tbody></table></div></div><?php page_end();exit;
}
